sp_EditarUsuario	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_EditarUsuario`(\n\n    IN p_idUsuario INT,\n\n    IN p_Nome      VARCHAR(100),\n\n    IN p_Login     VARCHAR(50),\n\n    IN p_Senha     VARCHAR(200),\n\n    IN p_CPF       VARCHAR(20),\n\n    IN p_Email     VARCHAR(100),\n\n    IN p_Telefone  VARCHAR(20),\n\n    IN p_cargo_id  TINYINT UNSIGNED\n\n)\nBEGIN\n\n    UPDATE Usuario SET\n\n        Nome     = p_Nome,\n\n        Login    = p_Login,\n\n        Senha    = CASE WHEN p_Senha IS NOT NULL AND p_Senha <> '' THEN p_Senha ELSE Senha END,\n\n        CPF      = p_CPF,\n\n        Email    = p_Email,\n\n        Telefone = p_Telefone,\n\n        cargo_id = p_cargo_id\n\n    WHERE idUsuario = p_idUsuario;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
